import { exec } from 'node:child_process';
export function register(app, db) {
  app.get('/admin/export', (req, res) => {
    exec('zip -r /tmp/' + req.query.name + '.zip data', (_e, out) => res.send(out));
  });
  app.get('/admin/users', async (req, res) => {
    const rows = await db.query(`SELECT * FROM users WHERE team = '${req.query.team}'`);
    res.json(rows);
  });
}

export function registerProfile(app, db, requireUser) {
  app.get('/profile', requireUser, async (req, res) => {
    const row = await db.query('SELECT * FROM users WHERE id = ?', [req.user.id]);
    res.json(row);
  });
}
